INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'shark', 'n.', '/ʃɑːk/', '鲨鱼', 'The great white shark is not the monster films make it out to be.', '大白鲨并不是电影里描绘的那种怪物。', 'Earth First', 1, 0, 'senior', 'wordlist', 'required2', 'U6', 'a great white shark', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'scare', 'v.', '/skeə/', '使惊恐;吓唬', 'The film scared many people into hating sharks.', '那部电影把许多人吓得开始憎恨鲨鱼。', 'Earth First', 2, 0, 'senior', 'wordlist', 'required2', 'U6', 'scare people', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'dive', 'v.', '/daɪv/', '潜水', 'Benchley loved to dive, and on one dive he saw the sea floor covered with dead sharks.', '本奇利热爱潜水,一次下潜时他看到海底布满了死鲨鱼。', 'Earth First', 3, 0, 'senior', 'wordlist', 'required2', 'U6', 'dive in the sea', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'target', 'v.', '/ˈtɑːɡɪt/', '把……作为目标;瞄准', 'Experts say that sharks do not target humans on purpose.', '专家说,鲨鱼并不会故意把人当作攻击目标。', 'Earth First', 4, 0, 'senior', 'wordlist', 'required2', 'U6', 'target humans', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fortunately', 'adv.', '/ˈfɔːtʃ(ə)nətli/', '幸运地', 'Fortunately, more and more people now want to protect sharks.', '幸运的是,如今越来越多的人想要保护鲨鱼。', 'Earth First', 5, 0, 'senior', 'wordlist', 'required2', 'U6', 'fortunately for us', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'extinction', 'n.', '/ɪkˈstɪŋkʃ(ə)n/', '灭绝;绝种', 'Many sea animals are now close to extinction.', '许多海洋动物如今已濒临灭绝。', 'Earth First', 6, 0, 'senior', 'wordlist', 'required2', 'U6', 'protect from extinction', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'attitude', 'n.', '/ˈætɪtjuːd/', '态度;看法', 'People''s attitude towards sharks has slowly changed.', '人们对鲨鱼的态度已经慢慢改变。', 'Earth First', 7, 0, 'senior', 'wordlist', 'required2', 'U6', 'change one''s attitude', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'devote', 'v.', '/dɪˈvəʊt/', '致力;献身;倾注', 'She has devoted her life to protecting ocean animals.', '她把一生都献给了保护海洋动物的事业。', 'Earth First', 8, 0, 'senior', 'wordlist', 'required2', 'U6', 'devote oneself to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ocean', 'n.', '/ˈəʊʃ(ə)n/', '海洋;大海', 'Plastic waste is doing great harm to ocean life.', '塑料垃圾正给海洋生物带来巨大伤害。', 'Earth First', 9, 0, 'senior', 'wordlist', 'required2', 'U6', 'ocean life', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'highlight', 'v.', '/ˈhaɪlaɪt/', '强调;使突出', 'The documentary highlights the cruelty of shark hunting.', '这部纪录片着重揭示了捕鲨的残忍。', 'Earth First', 10, 0, 'senior', 'wordlist', 'required2', 'U6', 'highlight the cruelty', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'cruelty', 'n.', '/ˈkruːəlti/', '残忍;残酷', 'Finning is an act of great cruelty to sharks.', '割鳍是对鲨鱼极其残忍的行为。', 'Earth First', 11, 0, 'senior', 'wordlist', 'required2', 'U6', 'cruelty to animals', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'hunting', 'n.', '/ˈhʌntɪŋ/', '打猎;狩猎', 'Years of hunting have made shark numbers fall quickly.', '多年的捕杀使鲨鱼数量迅速下降。', 'Earth First', 12, 0, 'senior', 'wordlist', 'required2', 'U6', 'shark hunting', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'presentation', 'n.', '/ˌprez(ə)nˈteɪʃ(ə)n/', '报告;陈述;展示', 'She travels the world giving presentations about ocean conservation.', '她周游世界,做有关海洋保护的报告。', 'Earth First', 13, 0, 'senior', 'wordlist', 'required2', 'U6', 'give a presentation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'reserve', 'n.', '/rɪˈzɜːv/', '(野生生物)保护区', 'The nature reserve protects rare plants and animals.', '这个自然保护区保护着珍稀的动植物。', 'Earth First', 14, 0, 'senior', 'wordlist', 'required2', 'U6', 'a nature reserve', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'staff', 'n.', '/stɑːf/', '员工;全体职员', 'Lin Feng is a staff member working at the reserve.', '林峰是在保护区工作的一名员工。', 'Earth First', 15, 0, 'senior', 'wordlist', 'required2', 'U6', 'a staff member', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'establish', 'v.', '/ɪˈstæblɪʃ/', '建立;设立', 'The reserve was established in the year 2000.', '这个保护区建立于2000年。', 'Earth First', 16, 0, 'senior', 'wordlist', 'required2', 'U6', 'establish a reserve', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'damage', 'v.', '/ˈdæmɪdʒ/', '损害;破坏', 'Human activity has badly damaged the wetland.', '人类活动严重破坏了这片湿地。', 'Earth First', 17, 0, 'senior', 'wordlist', 'required2', 'U6', 'damage the wetland', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'drought', 'n.', '/draʊt/', '旱灾;干旱', 'A long drought left the river almost dry.', '长期干旱使河流几乎干涸。', 'Earth First', 18, 0, 'senior', 'wordlist', 'required2', 'U6', 'a long drought', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'flood', 'n.', '/flʌd/', '洪水;水灾', 'Heavy floods have damaged many homes near the river.', '洪水冲毁了河边的许多房屋。', 'Earth First', 19, 0, 'senior', 'wordlist', 'required2', 'U6', 'heavy floods', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'affect', 'v.', '/əˈfekt/', '影响', 'These changes affect the water supply for people downstream.', '这些变化影响着下游居民的用水供应。', 'Earth First', 20, 0, 'senior', 'wordlist', 'required2', 'U6', 'affect the water supply', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'supply', 'n.', '/səˈplaɪ/', '供应;供给(系统)', 'The drought has cut the water supply to many villages.', '旱灾减少了许多村庄的供水。', 'Earth First', 21, 0, 'senior', 'wordlist', 'required2', 'U6', 'the water supply', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'restore', 'v.', '/rɪˈstɔː/', '使恢复;修复', 'The staff work hard to restore the natural environment.', '工作人员努力修复自然环境。', 'Earth First', 22, 0, 'senior', 'wordlist', 'required2', 'U6', 'restore the environment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'adopt', 'v.', '/əˈdɒpt/', '采取(方法);采用', 'They adopt new, sustainable ways of feeding farm animals.', '他们采用新的、可持续的方式来饲养家畜。', 'Earth First', 23, 0, 'senior', 'wordlist', 'required2', 'U6', 'adopt new ways', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sustainable', 'adj.', '/səˈsteɪnəb(ə)l/', '可持续的;不破坏环境的', 'We need a more sustainable way of living on the Earth.', '我们需要一种更可持续的地球生活方式。', 'Earth First', 24, 0, 'senior', 'wordlist', 'required2', 'U6', 'a sustainable way', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'carbon', 'n.', '/ˈkɑːbən/', '碳', 'Riding a bike helps to reduce your carbon footprint.', '骑自行车有助于减少你的碳足迹。', 'Earth First', 25, 0, 'senior', 'wordlist', 'required2', 'U6', 'carbon footprint', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'greenhouse', 'n.', '/ˈɡriːnhaʊs/', '温室;暖房', 'Cars and factories produce a lot of greenhouse gases.', '汽车和工厂会产生大量温室气体。', 'Earth First', 26, 0, 'senior', 'wordlist', 'required2', 'U6', 'greenhouse gases', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'brochure', 'n.', '/ˈbrəʊʃə/', '小册子', 'The brochure lists six things you can do to help the Earth.', '这本小册子列出了你可以为地球做的六件事。', 'Earth First', 27, 0, 'senior', 'wordlist', 'required2', 'U6', 'a green brochure', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'reduce', 'v.', '/rɪˈdjuːs/', '减少;降低', 'We can reduce waste by choosing reusable products.', '我们可以通过选用可重复使用的产品来减少浪费。', 'Earth First', 28, 0, 'senior', 'wordlist', 'required2', 'U6', 'reduce waste', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'solar', 'adj.', '/ˈsəʊlə/', '太阳能的;利用太阳光的', 'Solar panels turn sunlight into clean electricity.', '太阳能电池板把阳光转化为清洁的电力。', 'Earth First', 29, 0, 'senior', 'wordlist', 'required2', 'U6', 'solar energy', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'release', 'v.', '/rɪˈliːs/', '释放;排放', 'The less energy we use, the less carbon dioxide is released.', '我们使用的能源越少,排放的二氧化碳就越少。', 'Earth First', 30, 0, 'senior', 'wordlist', 'required2', 'U6', 'release carbon dioxide', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'smog', 'n.', '/smɒɡ/', '雾霾;烟雾', 'Thick smog often covers cities with heavy traffic.', '雾霾常常笼罩着交通繁忙的城市。', 'Earth First', 31, 0, 'senior', 'wordlist', 'required2', 'U6', 'thick smog', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fog', 'n.', '/fɒɡ/', '雾', 'The word smog is made from smoke and fog.', 'smog 一词由 smoke 和 fog 组成。', 'Earth First', 32, 0, 'senior', 'wordlist', 'required2', 'U6', 'smoke and fog', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'severe', 'adj.', '/sɪˈvɪə/', '严重的;剧烈的', 'Smog can cause severe breathing problems.', '雾霾会引起严重的呼吸问题。', 'Earth First', 33, 0, 'senior', 'wordlist', 'required2', 'U6', 'severe breathing problems', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'infection', 'n.', '/ɪnˈfekʃ(ə)n/', '感染;传染病', 'Dirty air can cause coughs and infections.', '脏空气会引起咳嗽和感染。', 'Earth First', 34, 0, 'senior', 'wordlist', 'required2', 'U6', 'cause infections', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'lecture', 'n.', '/ˈlektʃə/', '讲座;讲课', 'We listened to a lecture about smog and clean air.', '我们听了一场关于雾霾和清洁空气的讲座。', 'Earth First', 35, 0, 'senior', 'wordlist', 'required2', 'U6', 'give a lecture', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'permission', 'n.', '/pəˈmɪʃ(ə)n/', '允许;许可', 'A student asked the lecturer for permission to interrupt.', '一名学生请求讲师允许自己插话提问。', 'Earth First', 36, 0, 'senior', 'wordlist', 'required2', 'U6', 'ask for permission', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'slide', 'n.', '/slaɪd/', '幻灯片', 'The next slide shows the causes of smog today.', '下一张幻灯片展示了如今雾霾的成因。', 'Earth First', 37, 0, 'senior', 'wordlist', 'required2', 'U6', 'complete the slides', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'majority', 'n.', '/məˈdʒɒrəti/', '多数;大多数', 'The majority of us take steps to save energy.', '我们中的大多数人都会采取行动来节约能源。', 'Earth First', 38, 0, 'senior', 'wordlist', 'required2', 'U6', 'the majority of us', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'false', 'adj.', '/fɔːls/', '错误的;不正确的', 'Some so-called green truths are only half true or even false.', '一些所谓的环保真理只对了一半,甚至完全是错的。', 'Earth First', 39, 0, 'senior', 'wordlist', 'required2', 'U6', 'half true or false', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'amount', 'n.', '/əˈmaʊnt/', '数量;数额', 'Making a paper bag uses a large amount of water.', '制作一个纸袋要耗费大量的水。', 'Earth First', 40, 0, 'senior', 'wordlist', 'required2', 'U6', 'the amount of water', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'device', 'n.', '/dɪˈvaɪs/', '设备;装置', 'When you turn off a device, it often goes into stand-by mode.', '你关掉一台设备时,它常常进入待机状态。', 'Earth First', 41, 0, 'senior', 'wordlist', 'required2', 'U6', 'turn off a device', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'electricity', 'n.', '/ɪˌlekˈtrɪsɪti/', '电;电力', 'Devices in stand-by mode still use electricity.', '处于待机状态的设备仍在耗电。', 'Earth First', 42, 0, 'senior', 'wordlist', 'required2', 'U6', 'save electricity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'leak', 'v.', '/liːk/', '渗漏;漏出', 'Electricity continues to leak from the device even when it looks off.', '即使设备看起来已关闭,电仍在不断漏出。', 'Earth First', 43, 0, 'senior', 'wordlist', 'required2', 'U6', 'leak from a device', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'remove', 'v.', '/rɪˈmuːv/', '移走;去掉', 'To make sure it is really off, remove the plug from the socket.', '为确保彻底关闭,请把插头从插座上拔下来。', 'Earth First', 44, 0, 'senior', 'wordlist', 'required2', 'U6', 'remove the plug', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'plug', 'n.', '/plʌɡ/', '(电)插头', 'Pulling out the plug stops the appliance from wasting power.', '拔掉插头能让电器不再浪费电。', 'Earth First', 45, 0, 'senior', 'wordlist', 'required2', 'U6', 'pull out the plug', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'campaign', 'n.', '/kæmˈpeɪn/', '(宣传)活动;运动', 'Our class started a campaign to stop wasting food.', '我们班发起了一场反对浪费食物的活动。', 'Earth First', 46, 0, 'senior', 'wordlist', 'required2', 'U6', 'join a campaign', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'urge', 'v.', '/ɜːdʒ/', '敦促;强烈要求', 'The campaign urges people to save food at every meal.', '这场活动敦促人们每餐都节约食物。', 'Earth First', 47, 0, 'senior', 'wordlist', 'required2', 'U6', 'urge people to do', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'contribute', 'v.', '/kənˈtrɪbjuːt/', '促成;贡献;捐助', 'Each small action contributes to a greener Earth.', '每个小小的行动都会为更绿色的地球做出贡献。', 'Earth First', 48, 0, 'senior', 'wordlist', 'required2', 'U6', 'contribute to', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u6.01', '①-ing 分词作宾补(宾语主动发出、动作进行中)', 'A2', 10, '外研社版必修第二册 U6 — see/hear/watch/notice/find/catch/keep/leave + 宾语 + doing:宾语是动作的发出者、动作正在进行(I saw a shark swimming.)。', 1, 'required2', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u6.02', '②-ed 分词作宾补(宾语承受动作、动作已完成)', 'A2', 10, '外研社版必修第二册 U6 — find/have/get/keep/want/leave + 宾语 + done:宾语是动作的承受者、动作被完成(We found the door locked. / get the work done.)。', 2, 'required2', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u6.03', '③-ing 还是 -ed(由宾语与分词的主动/被动关系判断)', 'A2', 10, '外研社版必修第二册 U6 — 宾语主动发出动作→-ing;宾语承受动作→-ed。干扰项是相反语态或不定式,逐句看宾语和分词谁主动谁被动。', 3, 'required2', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'We see a woman ____ at night in a dark, cold sea.', 'swimming', 'swum', 'to swim', 'swims', 'A', '宾语 woman 自己在游、动作进行中,主动关系 → -ing 形式 swimming。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'Diving near the reef, Lin Feng noticed several fish ____ around the coral.', 'swum', 'swimming', 'to swim', 'swam', 'B', 'fish 自己在游、动作进行,主动 → swimming;swam 是过去式,不能作补语。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'All through the night we could hear the waves ____ against the rocks.', 'crashed', 'to crash', 'crashing', 'crashes', 'C', 'waves 自己拍打、动作进行 → crashing。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'On the beach the children found a baby turtle ____ slowly towards the sea.', 'moved', 'to move', 'moves', 'moving', 'D', 'turtle 自己在爬动、进行中 → moving。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'Suddenly we watched the great white shark ____ straight at the boat.', 'coming', 'came', 'to come', 'comes', 'A', 'shark 自己游过来、动作进行 → coming;came/comes 是谓语形式,不作补语。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'From the deck the tourists could see dolphins ____ out of the water.', 'jumped', 'jumping', 'to jump', 'jumps', 'B', 'dolphins 主动跳跃、进行中 → jumping。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'Walking by the river, I could smell something ____ in the dirty water.', 'rotted', 'to rot', 'rotting', 'rots', 'C', 'something 自己在腐烂、进行中 → rotting。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'The guide kept the engine ____ so the boat would not drift away.', 'run', 'to run', 'runs', 'running', 'D', 'keep + 宾语 + doing,engine 主动运转、持续中 → running。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'Please don''t leave the tap ____ while you are brushing your teeth.', 'running', 'ran', 'to run', 'runs', 'A', 'leave + 宾语 + doing,water/tap 主动在流 → running。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'The ranger caught a man secretly ____ waste into the clean river.', 'dumped', 'dumping', 'to dump', 'dumps', 'B', 'catch sb doing,man 主动倾倒、进行中 → dumping。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'Early in the morning the staff noticed smoke ____ from the dry forest.', 'risen', 'to rise', 'rising', 'rises', 'C', 'smoke 自己升起、进行中 → rising。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'Visitors often see volunteers ____ rubbish along the nature trail.', 'collected', 'to collect', 'collects', 'collecting', 'D', 'volunteers 主动收集、进行中 → collecting。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'All morning we could hear birds ____ in the protected forest.', 'singing', 'sung', 'to sing', 'sings', 'A', 'birds 主动鸣唱、进行中 → singing。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'She felt the cold sea water slowly ____ into her diving boots.', 'leaked', 'leaking', 'to leak', 'leaks', 'B', 'water 自己渗入、进行中 → leaking。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'The opening scene shows a great white shark ____ swimmers near the shore.', 'attacked', 'to attack', 'attacking', 'attacks', 'C', 'shark 主动攻击、动作进行 → attacking。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'Standing on the cliff, we watched the huge waves ____ the old boat away.', 'carried', 'to carry', 'carries', 'carrying', 'D', 'waves 主动卷走、进行中 → carrying。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'Even indoors I can hear the strong wind ____ through the trees.', 'blowing', 'blown', 'to blow', 'blows', 'A', 'wind 主动吹、进行中 → blowing。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'The scientists observed the polar ice ____ faster than ever before.', 'melted', 'melting', 'to melt', 'melts', 'B', 'ice 自己融化、进行中 → melting。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'We found several children ____ plastic bottles out of the lake.', 'pulled', 'to pull', 'pulling', 'pulls', 'C', 'children 主动捞取、进行中 → pulling。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.01'), 'Looking down from the glass boat, the diver saw thousands of fish ____ past the reef.', 'passed', 'to pass', 'passes', 'passing', 'D', 'fish 主动游过、进行中 → passing。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'After the storm, we found large areas of forest ____ by the flood.', 'destroyed', 'destroying', 'to destroy', 'destroys', 'A', 'forest 被洪水摧毁,被动完成 → -ed 形式 destroyed。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'While diving, Benchley saw thousands of sharks ____ just for their fins.', 'killing', 'killed', 'to kill', 'kills', 'B', 'sharks 被杀,被动 → killed。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'The reserve wants the damaged wetland ____ as soon as possible.', 'restoring', 'to restore', 'restored', 'restores', 'C', 'wetland 被修复,被动 → restored。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'The staff try to keep the original forest ____ from fire and pollution.', 'protecting', 'to protect', 'protects', 'protected', 'D', 'keep + 宾语 + done,forest 被保护 → protected。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'Every summer the heavy rain leaves many low villages ____ under water.', 'flooded', 'flooding', 'to flood', 'floods', 'A', 'villages 被淹,被动 → flooded。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'The factory had its dirty water ____ before it reached the river.', 'cleaning', 'cleaned', 'to clean', 'cleans', 'B', 'have + 宾语 + done,water 被清理 → cleaned。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'You can get your empty bottles ____ at the recycling centre.', 'recycling', 'to recycle', 'recycled', 'recycles', 'C', 'get + 宾语 + done,bottles 被回收 → recycled。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'We were sad to see so many old trees ____ down to make paper.', 'cutting', 'to cut', 'cuts', 'cut', 'D', 'trees 被砍倒,被动完成 → 过去分词 cut。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'After the talk, she found her notebook ____ with new green ideas.', 'filled', 'filling', 'to fill', 'fills', 'A', 'notebook 被写满,被动 → filled。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'The government wants the amount of smog ____ in big cities.', 'reducing', 'reduced', 'to reduce', 'reduces', 'B', 'smog 被减少,被动 → reduced。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'He had the broken solar panel ____ on the roof last week.', 'repairing', 'to repair', 'repaired', 'repairs', 'C', 'have + 宾语 + done,panel 被修理 → repaired。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'Sadly, we often see local rivers ____ by waste from factories.', 'polluting', 'to pollute', 'pollutes', 'polluted', 'D', 'rivers 被污染,被动 → polluted。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'Please keep the windows ____ to save the heating in winter.', 'closed', 'closing', 'to close', 'closes', 'A', 'keep + 宾语 + done,windows 被关上 → closed。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'The Clear Your Plate campaign wants far less food ____ at every meal.', 'wasting', 'wasted', 'to waste', 'wastes', 'B', 'food 被浪费,被动 → wasted。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'After the long drought, farmers found their crops ____ by the dry weather.', 'ruining', 'to ruin', 'ruined', 'ruins', 'C', 'crops 被毁,被动 → ruined。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'We should get all these old appliances ____ off at the power supply.', 'switching', 'to switch', 'switches', 'switched', 'D', 'get + 宾语 + done,appliances 被关闭 → switched。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'The diver was shocked to see the sea floor ____ with dead sharks.', 'covered', 'covering', 'to cover', 'covers', 'A', 'sea floor 被覆盖,被动 → covered。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'Last spring the school had hundreds of young trees ____ along the river.', 'planting', 'planted', 'to plant', 'plants', 'B', 'have + 宾语 + done,trees 被种下 → planted。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'Make sure the plug is ____ from the socket before you go to bed.', 'removing', 'to remove', 'removed', 'removes', 'C', 'plug 被拔下,被动 → removed。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.02'), 'By evening the volunteers had all the rubbish ____ into large bags.', 'packing', 'to pack', 'packs', 'packed', 'D', 'have + 宾语 + done,rubbish 被装入 → packed。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'From the boat I saw the fishermen ____ the fins off the living sharks.', 'cutting', 'cut', 'to cut', 'to be cut', 'A', '宾语 fishermen 主动切割、动作进行 → cutting。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'Then I watched the helpless sharks ____ back into the cold sea.', 'throwing', 'thrown', 'to throw', 'to be throwing', 'B', '宾语 sharks 被扔回,被动 → thrown。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'Walking through the woods, we could hear dry leaves ____ under our feet.', 'crackled', 'to crackle', 'crackling', 'to be crackled', 'C', 'leaves 自己发出脆响、进行中 → crackling。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'When the ranger arrived, he found the reserve gate ____ for the night.', 'locking', 'to lock', 'to be locking', 'locked', 'D', 'gate 被锁上,被动完成 → locked。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'From the high hill we watched the river ____ over the dry fields.', 'flooding', 'flooded', 'to flood', 'to be flooded', 'A', 'river 自己漫过、进行中 → flooding。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'After the visit, the staff found the wetland badly ____ by human activity.', 'damaging', 'damaged', 'to damage', 'to be damaging', 'B', 'wetland 被破坏,被动 → damaged。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'We kept the small electric boat ____ so we could leave the bay quickly.', 'run', 'to run', 'running', 'to be run', 'C', 'boat/engine 主动运转、持续中 → running。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'The lecturer wants her report on smog ____ before the weekend.', 'finishing', 'to finish', 'to be finishing', 'finished', 'D', 'report 被完成,被动 → finished。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'Standing at the window, I noticed thick smog slowly ____ over the city.', 'spreading', 'spread', 'to spread', 'to be spread', 'A', 'smog 自己蔓延、进行中 → spreading。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'During the drought, the villagers had their water supply ____ for days.', 'cutting', 'cut', 'to cut', 'to be cutting', 'B', 'water supply 被切断,被动完成 → cut。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'Standing on the shore, we watched the evening tide slowly ____ in.', 'come', 'to come', 'coming', 'to be come', 'C', 'tide 自己涨上来、进行中 → coming。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'He was sad to see so much plastic ____ behind on the once-clean beach.', 'leaving', 'to leave', 'to be leaving', 'left', 'D', 'plastic 被遗留,被动 → left。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'Near the factory you can smell chemicals ____ in the warm afternoon air.', 'floating', 'floated', 'to float', 'to be floated', 'A', 'chemicals 自己飘浮、进行中 → floating。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'The teacher wants all the classroom lights ____ off after the lesson.', 'turning', 'turned', 'to turn', 'to be turning', 'B', 'lights 被关掉,被动 → turned。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'Through the bus window I saw heavy rain ____ down on the dry land.', 'poured', 'to pour', 'pouring', 'to be poured', 'C', 'rain 自己倾泻、进行中 → pouring。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'After her talk, she found her message box ____ with questions about sharks.', 'filling', 'to fill', 'to be filling', 'filled', 'D', 'box 被装满,被动 → filled。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'On planting day we watched the volunteers ____ young trees along the bank.', 'planting', 'planted', 'to plant', 'to be planted', 'A', 'volunteers 主动栽种、进行中 → planting。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'To save money and waste, he got his old bike ____ instead of buying a new one.', 'repairing', 'repaired', 'to repair', 'to be repairing', 'B', 'bike 被修理,被动 → repaired。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'At dawn we heard wild birds ____ again in the slowly recovering forest.', 'sung', 'to sing', 'singing', 'to be sung', 'C', 'birds 主动鸣唱、进行中 → singing。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U6' AND code='f2u6.03'), 'Scientists want these rare sea animals ____ from extinction before it is too late.', 'saving', 'to save', 'to be saving', 'saved', 'D', 'animals 被拯救,被动 → saved。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'How a Film Changed People''s Minds', 'In 1975, a film called Jaws appeared in cinemas around the world. It tells the story of a great white shark that attacks and kills swimmers at a holiday beach. The film was a huge success. It attracted enormous audiences and won many awards. However, it also changed the way people thought about sharks. People had always been a little afraid of sharks, but Jaws made things much worse. Many people who saw the film began to believe that all sharks were dangerous animals that wanted to eat humans. Some were so scared that they stopped swimming in the sea. Others started hunting sharks, killing as many as they could. At that time, almost nobody cared how many sharks were killed. In this way, a single film turned a misunderstood animal into a monster in people''s minds, and few stopped to ask whether the frightening picture was really true.', '记叙·电影《大白鲨》与对鲨鱼的恐惧', 149, '[{"q":"How did the film Jaws change people''s view of sharks?","answer":"A","options":["It made them far more afraid of sharks.","It made them love and protect sharks.","It had no effect on their feelings.","It taught them that sharks were harmless."],"explanation":"原文 ''People had always been a little afraid of sharks, but Jaws made things much worse'' 的转述。"},{"q":"What did some frightened people start to do?","answer":"B","options":["They started keeping sharks as pets.","They went hunting and killing sharks.","They swam in the sea far more often.","They made new films to praise sharks."],"explanation":"原文 ''Others started hunting sharks, killing as many as they could'' 的转述。"},{"q":"What does the writer suggest at the end of the passage?","answer":"A","options":["Few people checked whether the scary image was true.","Everyone knew at once that the film was false.","The film was based on careful science.","Sharks really do hunt humans for food."],"explanation":"末句 ''few stopped to ask whether the frightening picture was really true'' 的转述。"}]'::jsonb, '[{"word":"shark","cn":"鲨鱼"},{"word":"scare","cn":"使惊恐"},{"word":"hunting","cn":"捕杀"},{"word":"attitude","cn":"看法"}]'::jsonb, 2, 'required2', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Man Who Changed His Mind', 'After 1975, the number of large sharks around America fell quickly, and soon numbers dropped around the world. This was partly due to fear, but a bigger cause was finning. Finning is a kind of fishing in which sharks are caught and their fins are cut off. The fishermen then throw the living sharks back into the sea, where they die slowly. The fins are used to make soup. Peter Benchley, who wrote the book that the film was based on, was deeply changed by what he saw. While he was diving in 1980, he came across an area where the sea floor was covered with dead sharks. From that day on, he fought to protect them. He admitted that his book had given a false picture of sharks. Experts have since proved that sharks do not see people as food, and that they harm humans only by accident. In fact, only about six people are killed by sharks each year.', '记叙·割鳍与本奇利对鲨鱼态度的转变', 161, '[{"q":"What was the bigger cause of the fall in shark numbers?","answer":"B","options":["Only people''s fear of the sea.","A kind of fishing called finning.","A lack of food in the ocean.","Sudden changes in the weather."],"explanation":"原文 ''a bigger cause was finning'' 的转述。"},{"q":"How did Peter Benchley change after his dive in 1980?","answer":"C","options":["He started finning sharks himself.","He wrote another frightening book.","He began working to protect sharks.","He stopped caring about the sea."],"explanation":"原文 ''From that day on, he fought to protect them'' 的转述。"},{"q":"What have experts proved about sharks?","answer":"D","options":["They hunt humans as their main food.","They kill thousands of people every year.","They never come close to people at all.","They harm people only by accident, not on purpose."],"explanation":"原文 ''they harm humans only by accident'' 的转述;其余与原文相反。"}]'::jsonb, '[{"word":"dive","cn":"潜水"},{"word":"cruelty","cn":"残忍"},{"word":"false","cn":"错误的"},{"word":"target","cn":"把…作为目标"}]'::jsonb, 2, 'required2', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Small Steps Against Global Warming', 'Most of us know that the Earth is getting warmer, and many of us want to do something about it. The good news is that small daily choices can make a real difference. One simple step is to lower your carbon footprint by walking or cycling to school instead of going by car. Another is to use renewable energy, such as solar power or wind power, whenever you can. Saving electricity matters too: the less energy we use, the less carbon dioxide is released into the air. Replacing an ordinary light bulb with an LED bulb is a great start, because LED bulbs use far less power. Saving clean water is also important, since we use a lot of energy to make water safe to drink. Finally, planting trees helps a great deal, because young trees take in carbon dioxide from the air. None of these actions is difficult, yet together they can help slow down global warming.', '说明·应对全球变暖的日常小事', 158, '[{"q":"According to the text, what can small daily choices do?","answer":"A","options":["They can really help fight global warming.","They make no difference at all.","They only waste people''s time.","They make the Earth grow hotter."],"explanation":"原文 ''small daily choices can make a real difference'' 的转述。"},{"q":"Why is changing to an LED bulb a good idea?","answer":"B","options":["LED bulbs are far cheaper to buy.","LED bulbs need much less electricity.","LED bulbs give a much brighter light.","LED bulbs last only a short time."],"explanation":"原文 ''LED bulbs use far less power'' 的转述。"},{"q":"How does planting trees help, according to the passage?","answer":"C","options":["Trees give people fruit to eat.","Trees make the air much colder.","They take in carbon dioxide as they grow.","Trees quickly use up all the water."],"explanation":"原文 ''young trees take in carbon dioxide from the air'' 的转述。"}]'::jsonb, '[{"word":"carbon","cn":"碳"},{"word":"solar","cn":"太阳能的"},{"word":"release","cn":"排放"},{"word":"reduce","cn":"减少"}]'::jsonb, 2, 'required2', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Smog: Then and Now', 'The word ''smog'' comes from ''smoke'' and ''fog''. It is used to describe the dirty air that hangs over many cities. Smog can be dangerous, because it causes serious breathing problems and other illnesses. In the past, smog was mainly caused by people burning coal to heat their homes and to run factories. In December 1952, London suffered one of the worst cases of smog in history. For several days a thick, dark cloud lay over the city, and thousands of people became ill. Today, the causes of smog are different. In most modern cities, the main causes are traffic and factories rather than home fires. To fight the problem, many governments have made new rules. They control the kinds of fuel that factories may burn, and they limit the number of cars allowed into city centres. Thanks to these measures, the air in some cities is slowly becoming cleaner and safer to breathe.', '说明·伦敦雾霾的过去与现在', 154, '[{"q":"Where does the word ''smog'' come from?","answer":"D","options":["The words ''sun'' and ''fog''.","The words ''smoke'' and ''frog''.","The words ''smell'' and ''dog''.","The words ''smoke'' and ''fog''."],"explanation":"原文 ''The word smog comes from smoke and fog'' 的转述。"},{"q":"What caused most smog in the past?","answer":"A","options":["Burning coal in homes and factories.","Heavy traffic on busy roads.","Too many trees inside cities.","Strong winds blowing from the sea."],"explanation":"原文 ''smog was mainly caused by people burning coal to heat their homes and to run factories'' 的转述。"},{"q":"How do many governments fight smog today?","answer":"B","options":["By burning much more coal at home.","By controlling fuel and limiting cars in city centres.","By building many more factories.","By removing all the rules about fuel."],"explanation":"原文 ''control the kinds of fuel... limit the number of cars'' 的转述。"}]'::jsonb, '[{"word":"smog","cn":"雾霾"},{"word":"fog","cn":"雾"},{"word":"severe","cn":"严重的"},{"word":"infection","cn":"感染"}]'::jsonb, 2, 'required2', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Is Paper Really Greener?', 'Many people believe that paper shopping bags are better for the Earth than plastic ones. It is easy to see why. Plastic bags cause litter and can harm wild animals, which sometimes mistake them for food. Plastic also takes hundreds of years to break down, while paper breaks down much faster. For these reasons, paper bags seem like the greener choice. However, the truth is not so simple. Making a paper bag uses about four times as much energy as making a plastic bag, and up to three times as much water. The process also produces more greenhouse gases. So, although paper breaks down more quickly, it is not really the better choice. In fact, both kinds of bag are bad for the environment in different ways. The best answer is to avoid both: carry a strong, reusable bag whenever you go shopping, and use it again and again.', '议论·纸袋与塑料袋的''环保真相''', 149, '[{"q":"Why do many people think paper bags are greener?","answer":"C","options":["Paper bags are always far cheaper.","Paper bags can hold much more shopping.","Paper breaks down faster and causes less litter.","Paper bags never tear or break."],"explanation":"原文 ''Plastic also takes hundreds of years to break down, while paper breaks down much faster'' 等的转述。"},{"q":"What problem does making paper bags cause?","answer":"D","options":["It uses no water at all.","It produces no greenhouse gases.","It is much faster than making plastic.","It uses more energy and water than making plastic ones."],"explanation":"原文 ''Making a paper bag uses about four times as much energy... three times as much water'' 的转述。"},{"q":"What does the writer suggest doing?","answer":"A","options":["Carry a reusable bag and use it many times.","Always choose paper bags over plastic ones.","Stop going shopping completely.","Take a brand-new bag every single time."],"explanation":"末句 ''carry a strong, reusable bag... use it again and again'' 的转述。"}]'::jsonb, '[{"word":"amount","cn":"数量"},{"word":"greenhouse","cn":"温室"},{"word":"false","cn":"不正确的"},{"word":"reduce","cn":"减少"}]'::jsonb, 2, 'required2', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Reserve at the Source of the Rivers', 'Sanjiangyuan National Nature Reserve, in western China, was set up in the year 2000. It is the highest and the second largest nature reserve in the country. The reserve protects dramatic landscapes that change from high mountains to grasslands, and from forests to rivers. Most importantly, it holds the sources of three great rivers: the Yellow River, the Changjiang River and the Lancang River. In recent years, however, the reserve has faced serious problems. Large areas of wetland have been damaged by human activity, which has harmed the special plants and animals that live there. Workers have also seen more droughts and floods, and these changes affect the water supply for people living downstream. The job of the staff is to look after and repair the local environment. They keep parts of the land free from human touch, and they help local people find new and sustainable ways to raise their farm animals.', '说明·三江源自然保护区的挑战', 153, '[{"q":"When was the reserve set up?","answer":"B","options":["In 1952.","In the year 2000.","In 1975.","In 1980."],"explanation":"原文 ''was set up in the year 2000''。"},{"q":"Why is the reserve so important?","answer":"C","options":["It lies right next to the sea.","It has the most people in all of China.","It is where three great rivers begin.","It grows food for the whole country."],"explanation":"原文 ''it holds the sources of three great rivers'' 的转述。"},{"q":"What is the main job of the staff?","answer":"D","options":["To build new factories inside the reserve.","To remove all the wild animals.","To stop people visiting it forever.","To care for the land and repair the damage."],"explanation":"原文 ''look after and repair the local environment'' 的转述。"}]'::jsonb, '[{"word":"reserve","cn":"保护区"},{"word":"establish","cn":"建立"},{"word":"drought","cn":"干旱"},{"word":"sustainable","cn":"可持续的"}]'::jsonb, 2, 'required2', 'U6', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U6', 'Going Green at School', 'Our school has started a new project to help the (1)____. Last week, our teacher gave a (2)____ about climate change and asked us to take action. The first thing I did was to bring a (3)____ water bottle instead of buying plastic ones. I also try to (4)____ waste by using both sides of my paper. On sunny days, our classroom uses (5)____ power from panels on the roof, so we save a lot of (6)____. Before we leave, we always (7)____ off the lights and computers. We have also planted young trees in the (8)____ behind the gym, because trees take in carbon dioxide. Our teacher says that even small actions can (9)____ a lot to a greener world. I feel (10)____ that I am doing something useful for the Earth.', 133, 2, '[{"q":"1","answer":"A","options":["environment","machine","market","garden"],"explanation":"help the environment 帮助环境。"},{"q":"2","answer":"B","options":["holiday","lecture","price","game"],"explanation":"give a lecture 做讲座。"},{"q":"3","answer":"C","options":["broken","empty","reusable","frozen"],"explanation":"a reusable water bottle 可重复使用的水瓶。"},{"q":"4","answer":"D","options":["increase","enjoy","forget","reduce"],"explanation":"reduce waste 减少浪费。"},{"q":"5","answer":"A","options":["solar","heavy","angry","loud"],"explanation":"solar power 太阳能。"},{"q":"6","answer":"B","options":["weather","electricity","distance","silence"],"explanation":"save electricity 节约电力。"},{"q":"7","answer":"C","options":["jump","cry","turn","sleep"],"explanation":"turn off 关掉。"},{"q":"8","answer":"D","options":["ocean","factory","market","garden"],"explanation":"in the garden 在花园里。"},{"q":"9","answer":"A","options":["contribute","return","belong","listen"],"explanation":"contribute a lot to 为…贡献良多。"},{"q":"10","answer":"B","options":["afraid","proud","bored","angry"],"explanation":"feel proud 感到自豪。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U6', 'Saving Energy at Home', 'Many people think that switching off a (1)____ such as a television means it stops using power. In fact, this is not always (2)____. When you press the button, the device often goes into stand-by (3)____. In this state, it still uses a small (4)____ of electricity. Older machines can use even more, because power keeps (5)____ from them quietly. To make sure an appliance is really off, you should (6)____ the plug from the wall. Doing this can (7)____ the amount of electricity your home wastes. It also helps to lower your family''s (8)____ bills at the end of the month. My father was very (9)____ when he learned how much power our old TV was using. Now we unplug it every night, and we feel good about saving (10)____.', 131, 2, '[{"q":"1","answer":"C","options":["garden","river","device","lecture"],"explanation":"switch off a device 关掉一台设备。"},{"q":"2","answer":"D","options":["late","rich","busy","true"],"explanation":"not always true 并不总是对的。"},{"q":"3","answer":"A","options":["mode","price","noise","road"],"explanation":"stand-by mode 待机状态。"},{"q":"4","answer":"B","options":["picture","amount","holiday","season"],"explanation":"a small amount of electricity 少量的电。"},{"q":"5","answer":"C","options":["growing","smiling","leaking","dancing"],"explanation":"power keeps leaking 电不断漏出。"},{"q":"6","answer":"D","options":["paint","enjoy","borrow","remove"],"explanation":"remove the plug 拔掉插头。"},{"q":"7","answer":"A","options":["reduce","raise","repeat","return"],"explanation":"reduce the amount wasted 减少浪费量。"},{"q":"8","answer":"B","options":["music","electricity","traffic","weather"],"explanation":"electricity bills 电费账单。"},{"q":"9","answer":"C","options":["asleep","silent","surprised","absent"],"explanation":"was surprised 很惊讶。"},{"q":"10","answer":"D","options":["litter","smoke","noise","energy"],"explanation":"saving energy 节约能源。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U6', 'Why the Ocean Matters', 'The (1)____ covers most of our planet and is full of life. Sadly, human activity is putting it in great (2)____. Every year, millions of sharks are killed, and many sea animals are close to (3)____. Plastic waste is another serious problem, because animals often (4)____ it for food and eat it. Some brave people have decided to (5)____ their lives to protecting the sea. One artist, for example, swims with dolphins and sharks to (6)____ the cruelty of hunting. She gives talks and (7)____ all around the world to get more people (8)____. Thanks to people like her, more and more of us now (9)____ that the sea needs our help. If we all do something small, we can help to (10)____ the ocean for the future.', 128, 2, '[{"q":"1","answer":"A","options":["ocean","forest","desert","mountain"],"explanation":"the ocean covers most of the planet 海洋覆盖地球大部分。"},{"q":"2","answer":"B","options":["comfort","danger","silence","order"],"explanation":"in great danger 处于极大危险。"},{"q":"3","answer":"C","options":["holiday","victory","extinction","profit"],"explanation":"close to extinction 濒临灭绝。"},{"q":"4","answer":"D","options":["paint","repair","water","mistake"],"explanation":"mistake it for food 错把它当作食物。"},{"q":"5","answer":"A","options":["devote","sell","lose","waste"],"explanation":"devote their lives to 把生命献给。"},{"q":"6","answer":"B","options":["forget","highlight","hide","sell"],"explanation":"highlight the cruelty 揭示残忍。"},{"q":"7","answer":"C","options":["holidays","mistakes","presentations","gardens"],"explanation":"gives talks and presentations 做演讲和报告。"},{"q":"8","answer":"D","options":["asleep","absent","bored","involved"],"explanation":"get more people involved 让更多人参与进来。"},{"q":"9","answer":"A","options":["realise","forget","doubt","refuse"],"explanation":"realise that the sea needs help 意识到海洋需要帮助。"},{"q":"10","answer":"B","options":["pollute","protect","damage","waste"],"explanation":"protect the ocean 保护海洋。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U6', 'The Clear Your Plate Campaign', 'Last month, our class started a (1)____ called Clear Your Plate. Its goal is to (2)____ people to stop wasting food. Many students did not (3)____ that over thirty per cent of the world''s food is thrown away every year, while millions of people do not have (4)____ to eat. We were quite (5)____ about this problem, so we decided to act. First, we agreed not to (6)____ more food than we need in the school canteen. Second, when we eat in a restaurant, we take any (7)____ food home. Third, we (8)____ our families and friends to join us. Our teacher told us that cutting daily food waste by just five per cent could (9)____ many people from hunger. Now most of us finish everything on our (10)____, and we feel proud to help.', 135, 2, '[{"q":"1","answer":"C","options":["holiday","factory","campaign","garden"],"explanation":"start a campaign 发起一场活动。"},{"q":"2","answer":"D","options":["follow","ignore","copy","urge"],"explanation":"urge people to stop 敦促人们停止。"},{"q":"3","answer":"A","options":["realise","sell","paint","drive"],"explanation":"did not realise 没有意识到。"},{"q":"4","answer":"B","options":["ready","enough","asleep","absent"],"explanation":"do not have enough to eat 没有足够的食物。"},{"q":"5","answer":"C","options":["pleased","bored","concerned","hungry"],"explanation":"concerned about this problem 对这个问题感到担忧。"},{"q":"6","answer":"D","options":["throw","cook","grow","order"],"explanation":"order more food than we need 点超过所需的食物。"},{"q":"7","answer":"A","options":["leftover","frozen","fresh","raw"],"explanation":"leftover food 剩饭。"},{"q":"8","answer":"B","options":["stopped","encouraged","forced","paid"],"explanation":"encouraged friends to join 鼓励朋友加入。"},{"q":"9","answer":"C","options":["buy","sell","save","cook"],"explanation":"save many people from hunger 使许多人免于饥饿。"},{"q":"10","answer":"D","options":["books","phones","bikes","plates"],"explanation":"everything on our plates 盘子里的一切。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U6', 'Planting Trees by the River', 'This spring, our school carried out a tree-planting (1)____ near the river. Trees are important because they take in carbon dioxide and help (2)____ global warming. They also give homes to birds, and their roots stop the soil from being (3)____ away by rain. On planting day, the (4)____ of us came early in the morning. Each group was given young trees and a (5)____ of water. Our teacher showed us how to dig a hole and (6)____ the roots carefully with soil. By noon, we had planted hundreds of young (7)____ along the riverbank. We were tired but very (8)____ of our work. The head teacher said that, in a few years, this area would become a green (9)____ full of life. I learned that protecting the Earth can be hard work, but it (10)____ a real difference.', 139, 2, '[{"q":"1","answer":"A","options":["project","holiday","mistake","price"],"explanation":"a tree-planting project 植树项目。"},{"q":"2","answer":"B","options":["increase","reduce","enjoy","repeat"],"explanation":"help reduce global warming 帮助减缓全球变暖。"},{"q":"3","answer":"C","options":["painted","sold","washed","frozen"],"explanation":"the soil from being washed away 土壤被冲走。"},{"q":"4","answer":"D","options":["silence","weather","distance","majority"],"explanation":"the majority of us 我们中的大多数。"},{"q":"5","answer":"A","options":["supply","noise","price","season"],"explanation":"a supply of water 一份供水。"},{"q":"6","answer":"B","options":["throw","cover","sell","burn"],"explanation":"cover the roots with soil 用土覆盖根部。"},{"q":"7","answer":"C","options":["cars","books","trees","shops"],"explanation":"planted hundreds of young trees 种下数百棵小树。"},{"q":"8","answer":"D","options":["afraid","angry","bored","proud"],"explanation":"proud of our work 为自己的劳动自豪。"},{"q":"9","answer":"A","options":["place","price","noise","machine"],"explanation":"a green place full of life 充满生机的绿地。"},{"q":"10","answer":"B","options":["loses","makes","sells","forgets"],"explanation":"it makes a real difference 它真的能带来改变。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U6', 'Cycling to School', 'Every morning, I used to ask my father to (1)____ me to school by car. One day, our teacher gave a (2)____ about carbon footprints, and I learned that cars (3)____ a lot of carbon dioxide into the air. From that day on, I decided to (4)____ my carbon footprint. Now I ride my bike to school, which is good for the (5)____ and good for my health too. The fresh air in the morning makes me feel (6)____ and ready to study. My father was a little (7)____ at first, but soon he understood my (8)____. He even started cycling to work himself. Our whole family now tries to live in a more (9)____ way. We have learned that one small change can (10)____ to a cleaner and greener Earth.', 131, 2, '[{"q":"1","answer":"C","options":["sell","paint","drive","lose"],"explanation":"drive me to school 开车送我上学。"},{"q":"2","answer":"D","options":["garden","price","river","talk"],"explanation":"gave a talk about 做了关于…的讲解。"},{"q":"3","answer":"A","options":["release","save","clean","drink"],"explanation":"cars release carbon dioxide 汽车排放二氧化碳。"},{"q":"4","answer":"B","options":["raise","cut","paint","borrow"],"explanation":"cut my carbon footprint 减少碳足迹。"},{"q":"5","answer":"C","options":["traffic","noise","environment","machine"],"explanation":"good for the environment 对环境有益。"},{"q":"6","answer":"D","options":["asleep","afraid","angry","awake"],"explanation":"makes me feel awake 让我感到清醒。"},{"q":"7","answer":"A","options":["surprised","asleep","absent","silent"],"explanation":"a little surprised 起初有点惊讶。"},{"q":"8","answer":"B","options":["price","choice","garden","machine"],"explanation":"understood my choice 理解了我的选择。"},{"q":"9","answer":"C","options":["dangerous","careless","sustainable","noisy"],"explanation":"a more sustainable way 更可持续的方式。"},{"q":"10","answer":"D","options":["return","belong","refuse","contribute"],"explanation":"contribute to a greener Earth 为更绿色的地球出力。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·对话 Talking About Recycling', '外研社版必修第二册 U6 · dialogue', 3, 'Mia: Tom, what do you do with your empty bottles and cans?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·短文 What Is Smog', '外研社版必修第二册 U6 · passage', 2, 'The word smog comes from the words smoke and fog.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·对话 Saving Energy at Home', '外研社版必修第二册 U6 · dialogue', 3, 'Dad: Lily, why have you unplugged the television?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·短文 Protecting Sharks', '外研社版必修第二册 U6 · passage', 2, 'For many years, people were very afraid of sharks.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·对话 A Visit to a Nature Reserve', '外研社版必修第二册 U6 · dialogue', 3, 'Reporter: Lin Feng, can you tell us a little about this nature reserve?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·短文 A Green Tip', '外研社版必修第二册 U6 · passage', 2, 'Here is a simple tip to help the Earth every day.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write a Persuasive Letter about an Environmental Issue(就一个环境问题写一封倡议信)', 'A Persuasive Letter to Save Our Environment', '假设你是李华,学校环保社的成员。请就身边一个环境问题(如食物浪费/塑料垃圾/浪费用电),用英语写一封约100词的倡议信,内容包括:① 说明你担心的问题及其影响;② 给出两条具体可行的建议;③ 呼吁大家一起行动。注意:语气有礼貌而有说服力,可用分词作补语(如 keep the lights off, get rubbish recycled)。', 'Suppose you are Li Hua, a member of the school Green Club. Write a persuasive letter (about 100 words) about an environmental problem around you (e.g. food waste, plastic litter, wasting electricity). Include: 1) the problem you are concerned about and its effects; 2) two practical suggestions; 3) a call for everyone to act together. Be polite but persuasive.', '["说明问题与影响(We are writing to raise your awareness of … / We are concerned that …)","提出具体建议(We would like to suggest … / In order to improve the situation, we should …)","呼吁共同行动(We hope that you will join us in …)","语气礼貌而有说服力,可用分词作补语"]'::jsonb, 70, 100, 'Dear Friends,
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required2', 'U6', '{"title":"-ing 与 -ed 分词作补语速查","intro":"分词作补语用来说明宾语(或主语)的动作或状态。判断只看一件事:宾语和分词之间是主动还是被动。宾语主动发出动作、动作进行中 → 用 -ing;宾语承受动作、动作已完成 → 用 -ed。","table":{"headers":["分词形式","用法 / 例句 / 标志动词"],"rows":[["-ing 分词","宾语主动发出、动作进行中:see/hear/watch/notice/find/keep/leave + sb/sth doing(I saw a shark swimming.)"],["-ed 分词","宾语承受动作、动作已完成:find/have/get/keep/want/leave + sth done(We found the door locked.)"],["have/get sth done","请人做/使某事被完成:He had his bike repaired. / get the work done."],["主语补语","be/sit/stand 等后说明主语状态:The sea floor was covered with dead sharks."]]},"specialRules":[{"rule":"宾语是动作的发出者、动作进行中 → 用 -ing","mark":"keep the water running(水自己在流)"},{"rule":"宾语是动作的承受者、动作被完成 → 用 -ed","mark":"get the work done(work 被完成)"},{"rule":"see/hear/watch + sb doing 强调''正在进行'';作补语只用 doing/done,不用 to do","mark":"saw him crossing √ / saw him to cross ×"},{"rule":"have sb do(请某人做) ≠ have sth done(让某事被做);找别人做事用 -ed","mark":"have my hair cut(头发被剪)"}],"why":["补语说明宾语的状态:宾语和分词若是''谁来做''(主动)就用 -ing,若是''被怎样''(被动/完成)就用 -ed。先找出宾语,再问它是动作的发出者还是承受者,形式自然就定了。"],"gaokaoPoints":["语法填空/完成句子高频:see/hear/find/keep/have/get + 宾语 + 分词,按主动(-ing)/被动(-ed)选形式。","感官动词后接 doing(进行)或 do(全过程,主动),但只有变被动 be seen/heard to do 时才补回 to。"],"examVsReal":[{"exam":"We found the door locked.(书面规范紧凑)","real":"The door was locked, so we found it.","note":"考试爱考分词作补语的紧凑表达"},{"exam":"I heard someone calling my name.(强调进行中)","real":"I heard someone call my name.","note":"doing 强调正在进行,do 强调听到全过程,口语两者都常用"}]}'::jsonb, 'fltrp');
